function Invoke-UpgraderDockerDesktopProtectedLatest {
        param([string]$WingetPath)

        if ([string]::IsNullOrWhiteSpace($WingetPath) -or -not (Test-Path -LiteralPath $WingetPath -PathType Leaf)) {
            Write-Host '[upgrader] Docker Desktop latest check skipped: winget unavailable'
            return $true
        }

        # Do not launch hidden docker.exe probes from upgrader. Docker Desktop
        # upgrades are deferred unless explicitly handled by redocker/getdocker.
        $runningContainers = 1

        $beforeList = (& $WingetPath upgrade --id Docker.DockerDesktop --exact --include-unknown --accept-source-agreements --disable-interactivity 2>&1 | Out-String)
        if ($beforeList -match '(?i)(No available upgrade found|No installed package found matching input criteria|No newer package versions are available)') {
            Write-Host '[upgrader] Docker Desktop already latest or not winget-managed'
            $env:DOCKER_DESKTOP_UPGRADER_PROTECTED = '1'
            return $true
        }

        if ($runningContainers -gt 0) {
            Write-Warning ("Docker Desktop update is available but deferred to protect {0} running Docker container(s); no Docker restart/stop was attempted." -f $runningContainers)
            $env:DOCKER_DESKTOP_UPGRADER_PROTECTED = '1'
            return $true
        }

        Write-Host '[upgrader] Docker Desktop protected latest pass (silent, no interactive close/reboot requested)'
        $dockerArgs = @(
            'upgrade',
            '--id', 'Docker.DockerDesktop',
            '--exact',
            '--include-unknown',
            '--accept-package-agreements',
            '--accept-source-agreements',
            '--silent',
            '--disable-interactivity',
            '--force'
        )
        $dockerOutput = (& $WingetPath @dockerArgs 2>&1 | Out-String)
        if ($dockerOutput) { Write-Host $dockerOutput.Trim() }
        $ok = ($LASTEXITCODE -eq 0 -or $dockerOutput -match '(?i)(No available upgrade found|No newer package versions are available|Successfully (installed|upgraded|updated))')
        if ($dockerOutput -match '(?i)(restart|reboot|close Docker|application is currently running|installer failed)') {
            Write-Warning 'Docker Desktop installer requested/mentioned restart, close, or failure; leaving Docker running and letting the existing upgrader continue with other apps.'
        }
        $env:DOCKER_DESKTOP_UPGRADER_PROTECTED = '1'
        return [bool]$ok
    }

